'use strict';
const peoplePriceChecks=new Map();
let mapMode='people',peopleRoot='Nancy Pelosi',peopleExpanded=new Set(),peopleNodes=new Map(),peopleSize={width:1120,height:820};
// Only disclosed, non-imported purchases and sales. This is a transaction map, not a holdings estimate.
function peopleMapRows(records=signalData){const today=new Date().toISOString().slice(0,10);return records.filter(r=>['Purchase','Sale'].includes(r.type)&&r.quality!=='User-provided'&&tickerValid(r.ticker)&&r.traded<=today&&disclosedDate(r)&&disclosedDate(r)<=today).sort((a,b)=>b.traded.localeCompare(a.traded)||String(a.id).localeCompare(String(b.id)))}
function peopleMapChildren(node,records){
 if(node.kind==='coverage')return [];
 const candidates=node.kind==='person'?records.filter(r=>r.person===node.name):records.filter(r=>r.ticker===node.name&&r.person!==node.parentPerson),groups=new Map();
 for(const r of candidates){const name=node.kind==='person'?r.ticker:r.person,key=(node.kind==='person'?'stock:':'person:')+name;if(node.trail.includes(key))continue;if(!groups.has(name))groups.set(name,[]);groups.get(name).push(r)}
 return [...groups].map(([name,rows])=>{const kind=node.kind==='person'?'stock':'person';return {kind,name,rows,id:node.id+'/'+encodeURIComponent(kind+':'+name),trail:[...node.trail,kind+':'+name],parentPerson:kind==='stock'?node.name:node.parentPerson,via:kind==='person'?node.name:null,referenceRows:kind==='person'?node.rows:null}});
}
function peopleOverlap(rows,reference,days=30){let nearest=null;for(const a of rows.filter(r=>r.type==='Purchase'))for(const b of (reference||[]).filter(r=>r.type==='Purchase')){const gap=Math.round((Date.parse(a.traded)-Date.parse(b.traded))/86400000);if(!nearest||Math.abs(gap)<Math.abs(nearest.gap))nearest={gap,buy:a,reference:b}}return nearest&&Math.abs(nearest.gap)<=days?nearest:null}
function peopleTree(records){const root={kind:'person',name:peopleRoot,id:'root',trail:['person:'+peopleRoot],rows:records.filter(r=>r.person===peopleRoot)},nodes=[];
 function grow(n,depth=0){nodes.push(n);n.children=(n.id==='root'||peopleExpanded.has(n.id))?peopleMapChildren(n,records):[];if(n.kind==='person'&&n.id!=='root'&&peopleExpanded.has(n.id)&&!n.children.length)n.children=[{id:n.id+'/coverage',kind:'coverage',name:'Other trades',person:n.name,via:n.via,rows:[],trail:n.trail}];n.children.forEach(c=>grow(c,depth+1));n.height=Math.max(380,n.children.reduce((s,c)=>s+c.height+28,0)-28);return n}
 grow(root);const left=root.children.filter((_,i)=>i%2===0),right=root.children.filter((_,i)=>i%2===1),span=a=>a.reduce((s,c)=>s+c.height+28,0)-28,height=Math.max(420,span(left),span(right));root.x=0;root.y=height/2;
 function arrange(children,parent,side){let top=parent.y-span(children)/2;for(const n of children){n.x=parent.x+side*410;n.y=top+n.height/2;n.parent=parent;arrange(n.children,n,side);top+=n.height+28}}
 arrange(left,root,-1);arrange(right,root,1);const minX=Math.min(...nodes.map(n=>n.x))-185,minY=Math.min(...nodes.map(n=>n.y))-210,maxX=Math.max(...nodes.map(n=>n.x))+185,maxY=Math.max(...nodes.map(n=>n.y))+210;for(const n of nodes){n.x-=minX;n.y-=minY}return {root,nodes,width:maxX-minX,height:maxY-minY};
}
function setMapMode(mode){if(mapMode!==mode)$('#mapSearch').value='';mapMode=mode;$$('[data-map-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapMode===mode)));$('#mapCentreLabel').textContent=mode==='people'?'Central politician':'Central stock';$('#mapCompanySearch').hidden=mode==='people';$('#mapMode').value=mode;$('#mapPerson').hidden=mode!=='people';$('#mapTicker').hidden=mode==='people';$('#mapTicker').required=mode!=='people';$('#mapLeads').closest('label').hidden=mode==='people';$('#mapThesis').hidden=mode==='people'||!mapData?.nodes.some(n=>n.kind==='thesis');$('.board-jumps').hidden=mode==='people';$('#peopleCollapse').hidden=mode!=='people';$('#peopleCentre').hidden=mode!=='people';$('#mapSearch').placeholder=mode==='people'?'Find a person or ticker':'Find a clue or person';$('#mapLegend').textContent=mode==='people'?'Green: buy · red: sale · amber: both · shared trading ≠ personal connection':'Solid thread: source context · dashed: research hypothesis';$('#mapHint').textContent=mode==='people'?'Unfold a stock → other traders → their trades. Drag the sheet · pinch or +/− to zoom.':'Follow the threads. Tap a card to explore · drag to move · pinch or +/− to zoom.';}
function openPeopleMap(person=peopleRoot){if(person!==peopleRoot)peopleExpanded.clear();peopleRoot=person;mapRequest++;setMapMode('people');changeView('map');$('#mapPersonNames').innerHTML=[...new Set([...Object.keys(ROSTER),...signalData.map(r=>r.person)])].sort().map(p=>`<option${p===person?' selected':''}>${esc(p)}</option>`).join('');$('#mapPerson').value=person;boardReset=true;renderPeopleMap()}
function peopleReturn(r,mode){const p=chartActivityReturn(r,mode);return `<b class="${p?(p.pct>=0?'gain':'loss'):'muted'}">${p?percent(p):'—'}</b>`}
function peopleTradeSummary(rows){const buy=rows.find(r=>r.type==='Purchase'),sale=rows.find(r=>r.type==='Sale');return `<div class="people-trade-summary">${buy?`<span class="gain">● Bought ${date(buy.traded)}</span>`:''}${sale?`<span class="loss">● Sold ${date(sale.traded)}</span>`:''}</div>`}
function peopleCard(n,records){if(n.kind==='coverage')return `<section class="people-card people-coverage" data-people-card="${esc(n.id)}" style="left:${n.x-155}px;top:${n.y-190}px"><span class="people-kind">DISCLOSURE COVERAGE</span><h2>Other trades</h2><p>No other trades loaded for ${esc(n.person)}.</p><p class="people-meta">${esc(n.via)} is already connected. This does not mean they made no other trades.</p><div class="people-actions"><button data-people-activity="${esc(n.person)}">View all disclosed activity ↗</button></div></section>`;const r=n.rows[0],root=n.id==='root',children=peopleMapChildren(n,records),expanded=peopleExpanded.has(n.id),overlap=n.via?peopleOverlap(n.rows,n.referenceRows):null,party=ROSTER[n.name];
 const title=n.kind==='person'?n.name:n.name,sub=root?`${new Set(n.rows.map(r=>r.ticker)).size} stocks · ${n.rows.length} disclosed trades`:n.kind==='stock'?r?.company:`Also traded ${n.via}`;
 return `<section class="people-card ${root?'people-root':''} ${n.kind==='stock'?'people-stock':''}" data-people-card="${esc(n.id)}" style="left:${n.x-155}px;top:${n.y-190}px"><i class="board-pin" aria-hidden="true"></i><span class="people-kind">${root?'FOLLOW THE MONEY':n.kind==='stock'?'STOCK · '+esc(n.parentPerson):'OTHER TRADER'}</span><h2>${!root&&n.kind==='person'?`<button class="people-name" data-people-toggle="${esc(n.id)}" aria-expanded="${expanded}">${esc(title)}</button>`:esc(title)}</h2>${n.kind==='person'?politicianRole(n.name):''}<p class="people-sub">${esc(sub)}</p>${n.kind==='stock'?`<small class="map-buy-count">${new Set(records.filter(r=>r.ticker===n.name&&r.type==='Purchase').map(r=>r.person)).size} buyers · ${new Set(records.filter(r=>r.ticker===n.name&&r.type==='Sale').map(r=>r.person)).size} sellers in loaded history</small>`:''}${root?`<p class="people-root-copy">${n.rows.length?'Trades → stocks → other traders':'No trades in the loaded disclosures.'}</p><div class="people-shortcuts">${children.map(c=>`<button data-people-focus="${esc(c.id)}">${esc(c.name)}</button>`).join('')}</div><p class="people-meta">${esc(party?.party||'')} · ${esc(party?.state||'')} · Based on loaded disclosures</p>`:r?`<div class="people-dates"><span class="${r.type==='Sale'?'loss':'gain'}">${r.type==='Sale'?'Sold':'Bought'} <b>${date(r.traded)}</b></span><span>Disclosed <b>${date(disclosedDate(r))}</b></span></div><p class="people-amount">${esc(r.amount)} <small>· ${esc(r.owner)} · ${esc(r.asset)}</small></p>${n.kind==='stock'?`<div class="people-returns"><span>Stock since ${r.type==='Sale'?'sale':'buy'} ${peopleReturn(r,'traded')}</span><span>Since disclosure ${peopleReturn(r,'disclosed')}</span></div><small class="people-meta">${PRICES[r.ticker]?.asOf?'Stock close '+date(PRICES[r.ticker].asOf)+(PRICES[r.ticker].stale?' · stale':''):'Prices unavailable'} · ${r.asset==='Call options'?'underlying stock · ':''}${r.type==='Sale'?'sale · realized profit unknown':'latest buy'}</small>`:`<p class="people-overlap">${overlap?`${Math.abs(overlap.gap)} days ${overlap.gap<0?'before':overlap.gap>0?'after':'apart from'} ${esc(n.parentPerson.split(' ').at(-1))}’s buy`:'No buy within 30 days in loaded records'}</p><small class="people-meta">Personal relationship: not established</small>`}`:'<p>No disclosed trades loaded.</p>'}${!root?peopleTradeSummary(n.rows):''}<div class="people-actions">${!root?`<button data-people-records="${esc(n.id)}">${n.rows.length} trade${n.rows.length===1?'':'s'} ↗</button>`:''}${!root&&(children.length||n.kind==='person')?`<button class="people-unfold" data-people-toggle="${esc(n.id)}" aria-expanded="${expanded}">${expanded?'− Fold':(n.kind==='person'?'Other trades →':'+ '+children.length+' other traders')}</button>`:!root?`<small>${n.kind==='stock'?'No other traders loaded':'No other stocks loaded'}</small>`:''}${root?'<button data-people-reset>Fold all branches</button>':''}</div></section>`;
}
function renderPeopleMap(){if(mapMode!=='people')return;const records=peopleMapRows(),tree=peopleTree(records);peopleNodes=new Map(tree.nodes.map(n=>[n.id,n]));peopleSize={width:tree.width,height:tree.height};
 const edges=tree.nodes.filter(n=>n.parent).map(n=>{const p=n.parent,sign=n.x>p.x?1:-1,a=p.x+sign*155,b=n.x-sign*155,m=(a+b)/2;return `<path class="${n.kind==='coverage'?'people-coverage-thread':n.rows.some(r=>r.type==='Sale')?(n.rows.some(r=>r.type==='Purchase')?'people-mixed-thread':'people-sale-thread'):'people-buy-thread'}" d="M${a} ${p.y}C${m} ${p.y} ${m} ${n.y} ${b} ${n.y}"/>`}).join('');
 $('#mapCanvas').innerHTML=`<div id="boardWorld" class="board-world people-world" style="width:${tree.width}px;height:${tree.height}px"><svg class="people-threads" width="${tree.width}" height="${tree.height}" aria-hidden="true">${edges}</svg>${tree.nodes.map(n=>peopleCard(n,records)).join('')}</div>`;
 $('#mapStatus').textContent=`${peopleRoot} · ${tree.root.rows.length} trades · ${tree.nodes.length} unfolded card${tree.nodes.length===1?'':'s'}`;
 $('#mapCoverage').innerHTML='<p>All available households, not just featured profiles. Loaded public disclosures and saved price histories; refreshes with the app’s feeds. User imports excluded. Missing filings, amendments and unreported sales can change the picture.</p><p>Returns are stock-price changes, including for options, not realized profit. Disclosure return starts at the first closing price after disclosure. No personal proximity is inferred from trading overlap.</p>';
 $('#mapList').innerHTML=tree.nodes.map(n=>`<button class="map-list-row" data-people-focus="${esc(n.id)}"><b>${esc(n.name)}</b><span>${n.rows.length} trades${n.via?' · via '+esc(n.via):''}</span></button>`).join('');
 if(boardReset){if($('#mapCanvas').clientWidth>700)fitBoard();else focusPeopleNode('root');boardReset=false}else applyBoardPose();highlightPeopleSearch();if(typeof ensurePoliticianRatingPrices==='function')ensurePoliticianRatingPrices(tree.nodes.filter(n=>n.kind==='person').map(n=>n.name));if(typeof loadMarketPrices==='function')refreshPeopleMapPrices(tree.nodes.filter(n=>n.kind==='stock').map(n=>n.name));
}
function focusPeopleNode(id){const n=peopleNodes.get(id);if(!n)return;const r=$('#mapCanvas').getBoundingClientRect(),scale=Math.min(1,(r.width-24)/340);boardPose={scale,x:r.width/2-n.x*scale,y:r.height/2-n.y*scale};applyBoardPose()}
function togglePeopleNode(id){const anchor=peopleNodes.get(id);if(!anchor)return;const screen={x:anchor.x*boardPose.scale+boardPose.x,y:anchor.y*boardPose.scale+boardPose.y};if(peopleExpanded.has(id))peopleExpanded.delete(id);else peopleExpanded.add(id);renderPeopleMap();const next=peopleNodes.get(id);boardPose.x=screen.x-next.x*boardPose.scale;boardPose.y=screen.y-next.y*boardPose.scale;applyBoardPose()}
function focusPeopleBranch(id){const n=peopleNodes.get(id);if(!n)return;const nodes=[n,...(n.children||[])],r=$('#mapCanvas').getBoundingClientRect(),left=Math.min(...nodes.map(n=>n.x))-165,right=Math.max(...nodes.map(n=>n.x))+165,top=Math.min(...nodes.map(n=>n.y))-200,bottom=Math.max(...nodes.map(n=>n.y))+200,scale=Math.min(1,(r.width-20)/(right-left),(r.height-20)/(bottom-top));boardPose={scale,x:r.width/2-(left+right)/2*scale,y:r.height/2-(top+bottom)/2*scale};applyBoardPose()}
function showPeopleActivity(person){const today=new Date().toISOString().slice(0,10),rows=signalData.filter(r=>r.person===person&&r.quality!=='User-provided'&&r.traded<=today&&disclosedDate(r)&&disclosedDate(r)<=today).sort((a,b)=>b.traded.localeCompare(a.traded)),buys=rows.filter(r=>r.type==='Purchase'),others=rows.filter(r=>r.type!=='Purchase');const row=r=>`<article class="people-record"><b>${esc(r.type)} · ${esc(r.ticker)}</b><p>${esc(r.company)} · ${esc(r.asset)}<br>Traded ${date(r.traded)} · Disclosed ${date(disclosedDate(r))}<br>${esc(r.amount)} · ${esc(r.owner)}<br>${esc(r.quality||'Source record')}</p>${r.type==='Purchase'?`<div class="people-returns"><span>Stock since ${r.type==='Sale'?'sale':'buy'} ${peopleReturn(r,'traded')}</span><span>Since disclosure ${peopleReturn(r,'disclosed')}</span></div>`:''}${researchLink(r.source,'Source filing ↗')}</article>`;$('#mapDetail').innerHTML=`<h2>${esc(person)}</h2>${politicianRole(person)}<p>All loaded disclosures. Sales are separate from purchases.</p><h3>Purchases (${buys.length})</h3>${buys.map(row).join('')||'<p>No purchases loaded.</p>'}<h3>Sales & other activity (${others.length})</h3>${others.map(row).join('')||'<p>No other activity loaded.</p>'}<p class="muted">Incomplete filing coverage. Purchase returns use stock closes, not realized profit; options show underlying stock changes. Disclosure returns start at the first close after disclosure.</p>`;showMapInspector()}
function highlightPeopleSearch(){if(mapMode!=='people')return;const q=$('#mapSearch').value.trim().toLowerCase();$$('[data-people-card]').forEach(el=>{const n=peopleNodes.get(el.dataset.peopleCard);el.classList.toggle('people-match',!!q&&(n.name+' '+n.rows.map(r=>r.company+' '+r.person+' '+r.ticker).join(' ')).toLowerCase().includes(q))})}
function showPeopleRecords(id){const n=peopleNodes.get(id);if(!n)return;$('#mapDetail').innerHTML=`<small class="map-detail-status">Disclosed trades · ${esc(n.name)}</small><h2>${esc(n.kind==='stock'?n.parentPerson+' → '+n.name:n.name+(n.via?' → '+n.via:''))}</h2>${n.kind==='person'?politicianRole(n.name):politicianRole(n.parentPerson)}${n.via?`<p>Shared stock: ${esc(n.via)}. Personal relationship to ${esc(n.parentPerson)} is not established by the loaded sources.</p>`:''}${n.rows.map(r=>`<article class="people-record"><b>${esc(r.ticker)} · ${esc(r.person)}</b><p>${r.type==='Sale'?'Sold':'Bought'} ${date(r.traded)} · Disclosed ${date(disclosedDate(r))}<br>${esc(r.amount)} · ${esc(r.owner)} · ${esc(r.asset)}<br>${esc(r.quality||'Source record')}</p><div class="people-returns"><span>Stock since ${r.type==='Sale'?'sale':'buy'} ${peopleReturn(r,'traded')}</span><span>Since disclosure ${peopleReturn(r,'disclosed')}</span></div><small>${PRICES[r.ticker]?.asOf?'Close '+date(PRICES[r.ticker].asOf):'Price unavailable'}</small><p>${esc(r.notes||'')}</p>${researchLink(r.source,'Source filing ↗')}${r.summarySource?' · '+researchLink(r.summarySource,'Transcription source ↗'):''}</article>`).join('')}<p class="muted">Hypothetical stock price changes, not realized profit. Options show their underlying stock. Since disclosure starts at the first close after disclosure; excludes dividends, costs and taxes.</p>${n.kind==='stock'?`<button class="secondary" data-map="${esc(n.name)}">Stock research board ↗</button><button class="secondary" data-ticker="${esc(n.name)}">Price chart ↗</button>`:`<button class="secondary" data-people-root="${esc(n.name)}">Put ${esc(n.name)} at the centre</button>`}`;showMapInspector()}
if(typeof window!=='undefined'){
 $('#mapPersonNames').innerHTML=Object.keys(ROSTER).map(p=>`<option${p===peopleRoot?' selected':''}>${esc(p)}</option>`).join('');
 $('#mapMode').onchange=e=>{if(e.target.value==='people')openPeopleMap();else openResearchMap(mapTicker)};
 $('#mapPerson').onchange=e=>{if(politicianNames().includes(e.target.value)){peopleExpanded.clear();openPeopleMap(e.target.value)}};
 $$('[data-map-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mapMode==='people')openPeopleMap();else openResearchMap(mapTicker)});$('#mapCompanySearch').onclick=()=>openCommands('map');
 $('#peopleCollapse').onclick=()=>{peopleExpanded.clear();renderPeopleMap()};$('#peopleCentre').onclick=()=>focusPeopleNode('root');
 document.addEventListener('click',e=>{if(e.defaultPrevented)return;if(e.target.closest('#mapInspector')&&e.target.closest('[data-map],[data-ticker]'))$('#mapInspector').close();const card=e.target.closest('[data-people-card]');if(card&&!e.target.closest('button')){const n=peopleNodes.get(card.dataset.peopleCard);if(n?.kind==='person'&&n.id!=='root'){if(!peopleExpanded.has(n.id))togglePeopleNode(n.id);focusPeopleBranch(n.id)}else focusPeopleNode(card.dataset.peopleCard);}const toggle=e.target.closest('[data-people-toggle]'),detail=e.target.closest('[data-people-records]'),root=e.target.closest('[data-people-root]'),focus=e.target.closest('[data-people-focus]');if(toggle){togglePeopleNode(toggle.dataset.peopleToggle);if(peopleExpanded.has(toggle.dataset.peopleToggle))focusPeopleBranch(toggle.dataset.peopleToggle);}const activity=e.target.closest('[data-people-activity]');if(activity)showPeopleActivity(activity.dataset.peopleActivity);if(detail)showPeopleRecords(detail.dataset.peopleRecords);if(root){$('#mapInspector').close();peopleExpanded.clear();openPeopleMap(root.dataset.peopleRoot)}if(focus)focusPeopleNode(focus.dataset.peopleFocus);if(e.target.closest('[data-people-reset]')){peopleExpanded.clear();renderPeopleMap()}});
}

async function refreshPeopleMapPrices(symbols){const pending=[...new Set(symbols)].filter(s=>!peoplePriceChecks.has(s)||Date.now()-peoplePriceChecks.get(s)>15*60000).slice(0,12);if(!pending.length)return;pending.forEach(s=>peoplePriceChecks.set(s,Date.now()));await loadMarketPrices(pending);if(view==='map'&&mapMode==='people')renderPeopleMap()}
